"""Command line entry point for genome-variant-toolkit."""

from __future__ import annotations

import argparse
import json
import os
import sys
import tempfile
from collections.abc import Iterable, Iterator, Sequence

from . import __version__
from .alignment import PairwiseAlignment, align_pair
from .kmer import build_kmer_index
from .quality import ReadQualityError, filter_reads
from .sequence_io import (
    SequenceFormatError,
    SequenceRecord,
    SequenceValidationError,
    read_sequences,
    write_sequences,
)

# Read/parse/processing errors that make the invocation invalid usage.
# ReadQualityError is a ValueError subclass but is listed explicitly.
_READ_ERRORS = (
    SequenceFormatError,
    SequenceValidationError,
    ReadQualityError,
    ValueError,
)


def _positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"{value!r} is not a positive integer")
    if parsed <= 0:
        raise argparse.ArgumentTypeError(f"{value!r} is not a positive integer")
    return parsed


def _quality_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"{value!r} is not an integer in the range 0-93"
        )
    if not 0 <= parsed <= 93:
        raise argparse.ArgumentTypeError(
            f"{value!r} is not an integer in the range 0-93"
        )
    return parsed


def _nonnegative_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"{value!r} is not a non-negative integer"
        )
    if parsed < 0:
        raise argparse.ArgumentTypeError(
            f"{value!r} is not a non-negative integer"
        )
    return parsed


def _prefix(first: SequenceRecord, rest: Iterable[SequenceRecord]) -> Iterator[SequenceRecord]:
    yield first
    yield from rest


class _ArgumentParser(argparse.ArgumentParser):
    """Argument parser that reports errors as one line on stderr."""

    def error(self, message: str) -> None:
        sys.stderr.write(f"{self.prog}: error: {message}\n")
        raise SystemExit(2)


def _build_parser() -> argparse.ArgumentParser:
    parser = _ArgumentParser(
        prog="genome-variant-toolkit",
        description="Genomic variant analysis toolkit from reads to annotated calls",
    )
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")

    normalize = sub.add_parser(
        "normalize-sequences",
        help="read FASTA/FASTQ sequences and write them in a normalized form",
    )
    normalize.add_argument("input", help="input file, or '-' for standard input")
    normalize.add_argument(
        "--input-format",
        choices=("fasta", "fastq", "auto"),
        default="auto",
        help="input format (default: auto-detect from the first title line)",
    )
    normalize.add_argument(
        "--output-format",
        choices=("fasta", "fastq", "auto"),
        default="auto",
        help="output format (default: keep the detected input format)",
    )
    normalize.add_argument(
        "--output",
        default="-",
        help="output file, or '-' for standard output (default: standard output)",
    )
    normalize.add_argument(
        "--line-width",
        type=_positive_int,
        default=60,
        help="maximum FASTA sequence line width in characters (default: 60); "
        "FASTQ layout is always four lines per record",
    )

    filter_reads_cmd = sub.add_parser(
        "filter-reads",
        help="trim low-quality ends and filter FASTQ reads",
    )
    filter_reads_cmd.add_argument("input", help="FASTQ input file, or '-' for standard input")
    filter_reads_cmd.add_argument(
        "--min-end-quality",
        type=_quality_int,
        default=20,
        metavar="N",
        help="trim bases with Phred quality strictly below N from both ends "
        "(default: 20)",
    )
    filter_reads_cmd.add_argument(
        "--min-mean-quality",
        type=_quality_int,
        default=20,
        metavar="N",
        help="drop reads whose mean Phred quality is below N after trimming "
        "(default: 20)",
    )
    filter_reads_cmd.add_argument(
        "--min-length",
        type=_positive_int,
        default=30,
        metavar="N",
        help="drop reads shorter than N bases after trimming (default: 30)",
    )
    filter_reads_cmd.add_argument(
        "--output",
        default="-",
        help="output file, or '-' for standard output (default: standard output)",
    )

    kmer_index_cmd = sub.add_parser(
        "kmer-index",
        help="build a k-mer index and write it as JSON Lines",
    )
    kmer_index_cmd.add_argument("input", help="input file, or '-' for standard input")
    kmer_index_cmd.add_argument(
        "--input-format",
        choices=("fasta", "fastq", "auto"),
        default="auto",
        help="input format (default: auto-detect from the first title line)",
    )
    kmer_index_cmd.add_argument(
        "--k",
        type=_positive_int,
        required=True,
        metavar="N",
        help="k-mer length (a positive integer)",
    )
    kmer_index_cmd.add_argument(
        "--no-canonical",
        action="store_true",
        help="index k-mers on the forward strand only (default: canonicalize "
        "each k-mer against its reverse complement)",
    )
    kmer_index_cmd.add_argument(
        "--output",
        default="-",
        help="output file, or '-' for standard output (default: standard output)",
    )

    align_pair_cmd = sub.add_parser(
        "align-pair",
        help="align two single-record FASTA/FASTQ inputs pairwise",
    )
    align_pair_cmd.add_argument(
        "reference", help="reference input file, or '-' for standard input"
    )
    align_pair_cmd.add_argument(
        "query", help="query input file, or '-' for standard input"
    )
    align_pair_cmd.add_argument(
        "--reference-format",
        choices=("fasta", "fastq", "auto"),
        default="auto",
        help="reference input format (default: auto-detect)",
    )
    align_pair_cmd.add_argument(
        "--query-format",
        choices=("fasta", "fastq", "auto"),
        default="auto",
        help="query input format (default: auto-detect)",
    )
    align_pair_cmd.add_argument(
        "--mode",
        choices=("global", "local"),
        default="global",
        help="alignment mode (default: global)",
    )
    align_pair_cmd.add_argument(
        "--match",
        "--match-score",
        dest="match",
        type=_positive_int,
        default=2,
        metavar="N",
        help="match score, a positive integer (default: 2)",
    )
    align_pair_cmd.add_argument(
        "--mismatch",
        "--mismatch-penalty",
        dest="mismatch",
        type=_nonnegative_int,
        default=3,
        metavar="N",
        help="mismatch penalty, a non-negative integer (default: 3)",
    )
    align_pair_cmd.add_argument(
        "--gap-open",
        type=_nonnegative_int,
        default=5,
        metavar="N",
        help="gap opening penalty, a non-negative integer (default: 5)",
    )
    align_pair_cmd.add_argument(
        "--gap-extend",
        type=_nonnegative_int,
        default=2,
        metavar="N",
        help="gap extension penalty, a non-negative integer (default: 2)",
    )
    align_pair_cmd.add_argument(
        "--output",
        default="-",
        help="output file, or '-' for standard output (default: standard output)",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0

    if args.command is None:
        parser.print_help()
        return 0

    if args.command == "normalize-sequences":
        return _run_normalize(args, parser)

    if args.command == "filter-reads":
        return _run_filter_reads(args, parser)

    if args.command == "kmer-index":
        return _run_kmer_index(args, parser)

    if args.command == "align-pair":
        return _run_align_pair(args, parser)

    if args.command == "kmer-index":
        return _run_kmer_index(args, parser)

    parser.print_help()  # pragma: no cover - every subcommand is handled above
    return 0


def _run_normalize(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.input == "-":
        input_stream = sys.stdin
        close_input = False
    else:
        try:
            input_stream = open(args.input, "r", encoding="utf-8", newline="")
        except OSError as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 1
        close_input = True

    try:
        records: Iterable[SequenceRecord] = read_sequences(
            input_stream, format=args.input_format
        )
        output_format = args.output_format

        if output_format == "auto":
            # read_sequences resolves "auto" and validates lazily; peek at
            # the first record to learn the input format.
            try:
                first = next(records)
            except (SequenceFormatError, SequenceValidationError) as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 2
            output_format = "fastq" if first.quality is not None else "fasta"
            records = _prefix(first, records)

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            output_stream = sys.stdout
            close_output = False
        else:
            try:
                output_stream = open(args.output, "w", encoding="utf-8", newline="")
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
            close_output = True

        try:
            try:
                write_sequences(
                    records,
                    output_stream,
                    format=output_format,
                    line_width=args.line_width,
                )
            except (SequenceFormatError, SequenceValidationError, ValueError) as exc:
                # ValueError covers usage problems such as writing FASTA
                # records without quality values as FASTQ.
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 2
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
        finally:
            if close_output:
                try:
                    output_stream.close()
                except OSError as exc:
                    print(f"{parser.prog}: {exc}", file=sys.stderr)
                    return 1
    finally:
        if close_input:
            input_stream.close()

    return 0


def _run_filter_reads(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.input == "-":
        input_stream = sys.stdin
        close_input = False
    else:
        try:
            input_stream = open(args.input, "r", encoding="utf-8", newline="")
        except OSError as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 1
        close_input = True

    try:
        records: Iterable[SequenceRecord] = read_sequences(
            input_stream, format="fastq"
        )
        filtered = filter_reads(
            records,
            min_end_quality=args.min_end_quality,
            min_mean_quality=args.min_mean_quality,
            min_length=args.min_length,
        )

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            output_stream = sys.stdout
            close_output = False
            temporary_path = None
        else:
            output_stream, temporary_path = _open_temporary_output(
                args.output, parser
            )
            if output_stream is None:
                return 1
            close_output = True

        try:
            try:
                write_sequences(filtered, output_stream, format="fastq")
            except _READ_ERRORS as exc:
                if temporary_path is not None:
                    _discard_temporary(output_stream, temporary_path)
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 2
            except OSError as exc:
                if temporary_path is not None:
                    _discard_temporary(output_stream, temporary_path)
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1

            if temporary_path is not None:
                try:
                    output_stream.flush()
                    output_stream.close()
                    os.replace(temporary_path, args.output)
                except OSError as exc:
                    _discard_temporary(output_stream, temporary_path)
                    print(f"{parser.prog}: {exc}", file=sys.stderr)
                    return 1
        finally:
            # On failure the temporary file was already closed and removed
            # by _discard_temporary; on success it was closed explicitly
            # before os.replace. This only closes a still-open temp stream.
            if close_output and not output_stream.closed:
                try:
                    output_stream.close()
                except OSError:
                    pass
    finally:
        if close_input:
            input_stream.close()

    return 0


def _run_kmer_index(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.input == "-":
        input_stream = sys.stdin
        close_input = False
    else:
        try:
            input_stream = open(args.input, "r", encoding="utf-8", newline="")
        except OSError as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 1
        close_input = True

    try:
        records: Iterable[SequenceRecord] = read_sequences(
            input_stream, format=args.input_format
        )
        # Build the whole index before writing anything: all reading and
        # validation happens here, so a failure never produces partial
        # output or touches the output file.
        try:
            index = build_kmer_index(
                records, args.k, canonical=not args.no_canonical
            )
        except _READ_ERRORS as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 2
        except OSError as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 1

        lines = []
        for kmer, occurrences in index.items():
            lines.append(
                json.dumps(
                    {
                        "kmer": kmer,
                        "count": len(occurrences),
                        "occurrences": [
                            {
                                "record": occurrence.record,
                                "id": occurrence.id,
                                "position": occurrence.position,
                                "strand": occurrence.strand,
                            }
                            for occurrence in occurrences
                        ],
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
            )
        text = "".join(line + "\n" for line in lines)

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            try:
                sys.stdout.write(text)
                sys.stdout.flush()
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
            return 0

        output_stream, temporary_path = _open_temporary_output(
            args.output, parser, prefix=".kmer-index-"
        )
        if output_stream is None:
            return 1
        try:
            try:
                output_stream.write(text)
                output_stream.flush()
                output_stream.close()
                os.replace(temporary_path, args.output)
            except OSError as exc:
                _discard_temporary(output_stream, temporary_path)
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
        finally:
            if not output_stream.closed:
                try:
                    output_stream.close()
                except OSError:
                    pass
    finally:
        if close_input:
            input_stream.close()

    return 0


def _read_single_record(
    path: str,
    fmt: str,
    parser: argparse.ArgumentParser,
    label: str,
) -> tuple[SequenceRecord | None, object, bool, int]:
    """Read exactly one record from *path*.

    Returns ``(record, stream, close, exit_code)``; *record* is ``None``
    when the invocation failed and *exit_code* is then ``1`` or ``2``.
    ``"-"`` reads from standard input.
    """
    if path == "-":
        stream = sys.stdin
        close = False
    else:
        try:
            stream = open(path, "r", encoding="utf-8", newline="")
        except OSError as exc:
            print(f"{parser.prog}: {label}: {exc}", file=sys.stderr)
            return None, None, False, 1
        close = True

    try:
        records = read_sequences(stream, format=fmt)
        try:
            first = next(records)
        except StopIteration:
            raise SequenceFormatError(f"{label}: empty input")
        try:
            next(records)
        except StopIteration:
            return first, stream, close, 0
        raise SequenceFormatError(f"{label}: expected exactly one record, got more")
    except (SequenceFormatError, SequenceValidationError, ValueError) as exc:
        if close:
            stream.close()
        print(f"{parser.prog}: {exc}", file=sys.stderr)
        return None, None, False, 2
    except OSError as exc:
        if close:
            stream.close()
        print(f"{parser.prog}: {label}: {exc}", file=sys.stderr)
        return None, None, False, 1


def _alignment_to_json(result: PairwiseAlignment) -> str:
    return json.dumps(
        {
            "reference": result.reference,
            "query": result.query,
            "mode": result.mode,
            "score": result.score,
            "reference_start": result.reference_start,
            "reference_end": result.reference_end,
            "query_start": result.query_start,
            "query_end": result.query_end,
            "cigar": result.cigar,
            "aligned_reference": result.aligned_reference,
            "aligned_query": result.aligned_query,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )


def _run_align_pair(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.reference == "-" and args.query == "-":
        print(
            f"{parser.prog}: reference and query cannot both be read from standard input",
            file=sys.stderr,
        )
        return 2

    reference_record, ref_stream, close_ref, ref_code = _read_single_record(
        args.reference, args.reference_format, parser, "reference"
    )
    if reference_record is None:
        return ref_code

    query_record, query_stream, close_query, query_code = _read_single_record(
        args.query, args.query_format, parser, "query"
    )
    if query_record is None:
        if close_ref:
            ref_stream.close()
        return query_code

    try:
        try:
            result = align_pair(
                reference_record,
                query_record,
                mode=args.mode,
                match_score=args.match,
                mismatch_penalty=args.mismatch,
                gap_open=args.gap_open,
                gap_extend=args.gap_extend,
            )
        except (SequenceValidationError, ValueError) as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 2
        text = _alignment_to_json(result) + "\n"

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            try:
                sys.stdout.write(text)
                sys.stdout.flush()
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
            return 0

        output_stream, temporary_path = _open_temporary_output(
            args.output, parser, prefix=".align-pair-"
        )
        if output_stream is None:
            return 1
        try:
            try:
                output_stream.write(text)
                output_stream.flush()
                output_stream.close()
                os.replace(temporary_path, args.output)
            except OSError as exc:
                _discard_temporary(output_stream, temporary_path)
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
        finally:
            if not output_stream.closed:
                try:
                    output_stream.close()
                except OSError:
                    pass
    finally:
        if close_ref:
            ref_stream.close()
        if close_query:
            query_stream.close()

    return 0


def _discard_temporary(stream: object, path: str) -> None:
    """Close and remove a temporary output file after a failed run."""
    close = getattr(stream, "close", None)
    if callable(close):
        try:
            close()
        except OSError:
            pass
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass
    except OSError:
        pass


def _open_temporary_output(
    destination: str,
    parser: argparse.ArgumentParser,
    prefix: str = ".filter-reads-",
) -> tuple[object, str] | tuple[None, None]:
    """Create a temporary text file next to *destination*.

    Returns ``(stream, path)``; on failure prints one error line and
    returns ``(None, None)``.
    """
    output_dir = os.path.dirname(os.path.abspath(destination))
    try:
        fd, path = tempfile.mkstemp(
            dir=output_dir,
            prefix=prefix,
            suffix=".tmp",
        )
        # mkstemp creates files with mode 0600; match the mode a plain
        # open() would give the final output instead.
        current_umask = os.umask(0)
        os.umask(current_umask)
        os.fchmod(fd, 0o666 & ~current_umask)
    except OSError as exc:
        print(f"{parser.prog}: {exc}", file=sys.stderr)
        return None, None
    try:
        return os.fdopen(fd, "w", encoding="utf-8", newline=""), path
    except OSError as exc:
        try:
            os.close(fd)
        finally:
            try:
                os.unlink(path)
            except OSError:
                pass
        print(f"{parser.prog}: {exc}", file=sys.stderr)
        return None, None


if __name__ == "__main__":
    sys.exit(main())

"""FASTA/FASTQ reading and normalization.

Public API:

- :class:`SequenceRecord` — one sequence with identifier, description and
  optional per-base quality values.
- :func:`read_sequences` — lazily read records from a text path or text
  stream; the format is ``"fasta"``, ``"fastq"`` or ``"auto"``.
- :func:`write_sequences` — write records in FASTA or FASTQ form.

Sequences only contain the IUPAC DNA symbols ``ACGTRYSWKMBDHVN``.  FASTQ
quality values use the Phred+33 encoding with ASCII characters 33–126.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Iterator
from dataclasses import dataclass

__all__ = [
    "SequenceRecord",
    "SequenceFormatError",
    "SequenceValidationError",
    "read_sequences",
    "write_sequences",
]

_VALID_BASES = frozenset("ACGTRYSWKMBDHVN")
_INPUT_FORMATS = ("fasta", "fastq", "auto")
_OUTPUT_FORMATS = ("fasta", "fastq")


class SequenceFormatError(ValueError):
    """Malformed FASTA/FASTQ input (structure, identifiers, lengths)."""


class SequenceValidationError(ValueError):
    """A sequence contains a symbol outside the allowed IUPAC set."""


@dataclass(frozen=True)
class SequenceRecord:
    """A single sequence record.

    ``identifier`` is the first whitespace-delimited field of the title
    line; ``description`` holds the remainder (``""`` when absent).
    ``quality`` is ``None`` for FASTA records and a tuple of Phred scores
    for FASTQ records.
    """

    identifier: str
    sequence: str
    description: str = ""
    quality: tuple[int, ...] | None = None


def _clean_sequence(raw: str) -> str:
    """Strip in-line whitespace and upper-case a raw sequence fragment."""
    return "".join(raw.split()).upper()


def _validate_sequence(identifier: str, sequence: str) -> None:
    for position, symbol in enumerate(sequence, start=1):
        if symbol not in _VALID_BASES:
            raise SequenceValidationError(
                f"record {identifier!r}: invalid symbol {symbol!r} at position {position}"
            )


def _split_title(title: str, source: str, line_number: int) -> tuple[str, str]:
    fields = title.split(None, 1)
    if not fields:
        raise SequenceFormatError(f"{source}:{line_number}: empty sequence identifier")
    identifier = fields[0]
    description = fields[1] if len(fields) == 2 else ""
    return identifier, description


def _line_error(source: str, line_number: int, message: str) -> SequenceFormatError:
    return SequenceFormatError(f"{source}:{line_number}: {message}")


def _fasta_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")
        if line.startswith(">"):
            if header_line is not None:
                yield _finish_fasta(header_line, header_number, seq_parts, source)
            header_line = line
            header_number = number
            seq_parts = []
        elif line.strip():
            if header_line is None:
                raise _line_error(
                    source,
                    number,
                    "content before first title line (expected a line starting with '>')",
                )
            seq_parts.append(line)
        # Blank lines outside or inside a record are ignored.

    if header_line is not None:
        yield _finish_fasta(header_line, header_number, seq_parts, source)


def _finish_fasta(
    header_line: str, header_number: int, parts: list[str], source: str
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    sequence = _clean_sequence("".join(parts))
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    return SequenceRecord(identifier, sequence, description)


def _check_quality_segment(segment: str, source: str, line_number: int) -> None:
    for char in segment:
        value = ord(char)
        if value < 33 or value > 126:
            raise _line_error(
                source,
                line_number,
                f"quality character {char!r} is outside the ASCII 33-126 range",
            )


def _fastq_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    # State machine over logical lines.  Sequence and quality may each
    # span several physical lines; record boundaries are determined by the
    # '+' separator and the number of quality characters matching the
    # sequence length.
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []
    qual_segments: list[str] = []
    in_quality = False

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")

        if header_line is None:
            if not line:
                raise _line_error(
                    source,
                    number,
                    "incomplete FASTQ record (expected a title line starting with '@')",
                )
            if not line.startswith("@"):
                raise _line_error(
                    source, number, "expected a FASTQ title line starting with '@'"
                )
            header_line = line
            header_number = number
            seq_parts = []
            qual_segments = []
            in_quality = False
            continue

        if not in_quality:
            if line.startswith("+"):
                plus_title = line[1:]
                if plus_title and plus_title != header_line[1:]:
                    raise _line_error(
                        source,
                        number,
                        "FASTQ separator title does not match the record title",
                    )
                if not _clean_sequence("".join(seq_parts)):
                    raise _line_error(source, header_number, "empty sequence")
                in_quality = True
            else:
                if not line.strip():
                    raise _line_error(source, number, "empty sequence")
                seq_parts.append(line)
            continue

        if not line:
            raise _line_error(source, number, "incomplete FASTQ record (missing quality values)")
        _check_quality_segment(line, source, number)
        qual_segments.append(line)

        sequence = _clean_sequence("".join(seq_parts))
        quality_text = "".join(qual_segments)
        if len(quality_text) > len(sequence):
            raise _line_error(
                source,
                number,
                f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
            )
        if len(quality_text) == len(sequence):
            yield _finish_fastq(
                header_line, header_number, sequence, quality_text, source
            )
            header_line = None

    if header_line is not None:
        raise _line_error(source, header_number, "incomplete FASTQ record")


def _finish_fastq(
    header_line: str,
    header_number: int,
    sequence: str,
    quality_text: str,
    source: str,
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    if len(quality_text) != len(sequence):
        raise _line_error(
            source,
            header_number,
            f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
        )
    quality = tuple(ord(char) - 33 for char in quality_text)
    return SequenceRecord(identifier, sequence, description, quality)


def _enumerate_lines(stream: Iterable[str]) -> Iterator[tuple[int, str]]:
    for number, line in enumerate(stream, start=1):
        yield number, line


def read_sequences(
    source: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "auto",
) -> Iterator[SequenceRecord]:
    """Lazily read sequence records from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  *format* is ``"fasta"``, ``"fastq"``
    or ``"auto"``; with ``"auto"`` the format is detected from the first
    non-empty line (``>`` → FASTA, ``@`` → FASTQ).

    Records are produced in input order.  Errors raised while opening a
    path propagate as :class:`OSError`; malformed input raises
    :class:`SequenceFormatError` or :class:`SequenceValidationError`
    during iteration and are never swallowed.
    """
    if format not in _INPUT_FORMATS:
        raise ValueError(
            f"unsupported format {format!r}; expected one of {', '.join(_INPUT_FORMATS)}"
        )

    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        yield from _read_from_stream(stream, source_name, format)
    finally:
        if close:
            stream.close()


def _read_from_stream(
    stream: Iterable[str], source_name: str, format: str
) -> Iterator[SequenceRecord]:
    numbered = _enumerate_lines(stream)

    first_number = 0
    first_line: str | None = None
    for number, raw_line in numbered:
        candidate = raw_line.rstrip("\r\n")
        if candidate.strip():
            first_number = number
            first_line = candidate
            break

    if first_line is None:
        if format == "auto":
            raise SequenceFormatError(
                f"{source_name}: empty input; cannot determine format"
            )
        raise SequenceFormatError(f"{source_name}: empty input")

    if format == "auto":
        if first_line.startswith(">"):
            detected = "fasta"
        elif first_line.startswith("@"):
            detected = "fastq"
        else:
            raise _line_error(
                source_name,
                first_number,
                "cannot determine format: first non-empty line must start with '>' or '@'",
            )
    else:
        detected = format

    def replay() -> Iterator[tuple[int, str]]:
        yield first_number, first_line + "\n"
        yield from numbered

    # The per-format parsers reject a first line that lacks their title
    # marker themselves (reported as content before / unexpected title).
    if detected == "fasta":
        yield from _fasta_records(replay(), source_name)
    else:
        yield from _fastq_records(replay(), source_name)


def write_sequences(
    records: Iterable[SequenceRecord],
    output: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "fasta",
    line_width: int = 60,
) -> None:
    """Write *records* to *output* in FASTA or FASTQ form.

    FASTA sequences are wrapped at *line_width* characters (a positive
    integer); FASTQ always uses the fixed four-line layout regardless of
    *line_width*.  Records without quality values cannot be written as
    FASTQ.  Output uses ``"\\n"`` line endings and ends with exactly one
    trailing newline.
    """
    if format not in _OUTPUT_FORMATS:
        raise ValueError(f"unsupported format {format!r}; expected 'fasta' or 'fastq'")
    if not isinstance(line_width, int) or isinstance(line_width, bool) or line_width <= 0:
        raise ValueError("line_width must be a positive integer")

    if isinstance(output, io.IOBase):
        stream: io.TextIOBase = output
        close = False
    elif isinstance(output, (str, os.PathLike)):
        stream = open(os.fspath(output), "w", encoding="utf-8", newline="")
        close = True
    else:
        raise TypeError("output must be a text path or a text stream")

    try:
        for record in records:
            _validate_sequence(record.identifier, record.sequence)
            if format == "fasta":
                stream.write(_format_fasta_record(record, line_width))
            else:
                stream.write(_format_fastq_record(record))
    finally:
        if close:
            stream.close()


def _format_title(record: SequenceRecord) -> str:
    if record.description:
        return record.identifier + " " + record.description
    return record.identifier


def _format_fasta_record(record: SequenceRecord, line_width: int) -> str:
    parts = [">" + _format_title(record) + "\n"]
    sequence = record.sequence
    for start in range(0, len(sequence), line_width):
        parts.append(sequence[start : start + line_width])
        parts.append("\n")
    return "".join(parts)


def _format_fastq_record(record: SequenceRecord) -> str:
    if record.quality is None:
        raise ValueError(
            f"record {record.identifier!r} has no quality values; cannot write it as FASTQ"
        )
    if len(record.quality) != len(record.sequence):
        raise ValueError(
            f"record {record.identifier!r}: quality length does not match sequence length"
        )
    quality_chars = []
    for value in record.quality:
        if not 0 <= value <= 93:
            raise ValueError(
                f"record {record.identifier!r}: quality score {value} is outside the "
                "Phred+33 range 0-93"
            )
        quality_chars.append(chr(value + 33))
    title = _format_title(record)
    return f"@{title}\n{record.sequence}\n+{title}\n{''.join(quality_chars)}\n"

input.content:
"""Reference-aware VCF reading, normalization and writing.

Public API:

- :class:`VcfHeader` — the ``##`` meta-information lines (kept verbatim
  and in order) together with the sample names declared by the single
  ``#CHROM`` column header.
- :class:`VcfRecord` — one VCF data row: the eight fixed columns, an
  optional ``FORMAT`` column and the per-sample text columns.
- :class:`VcfFile` — a parsed VCF document pairing a header with its
  records.
- :func:`read_vcf` — parse VCF text from a path or text stream.
- :func:`normalize_record` / :func:`normalize_vcf` — trim common
  allele suffixes/prefixes and left-align indels against a reference.
- :func:`write_vcf` — serialize a VCF document with tabs and ``"\\n"``.

Ordinary sequence alleles only contain the IUPAC DNA symbols
``ACGTRYSWKMBDHVN`` (lower-case input is upper-cased).  Records carrying
symbolic (``<...>``), break-end (``]``/``[``) or spanning (``*``) ALT
alleles are validated against the reference but never trimmed or
shifted.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Iterator, Mapping, Sequence
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord, _VALID_BASES

__all__ = [
    "VcfHeader",
    "VcfRecord",
    "VcfFile",
    "VcfFormatError",
    "ReferenceMismatchError",
    "read_vcf",
    "normalize_record",
    "normalize_vcf",
    "write_vcf",
]

_FIXED_COLUMNS = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")
_MIN_COLUMNS = 8


class VcfFormatError(ValueError):
    """Malformed VCF input (missing/duplicate header, bad columns or fields)."""


class ReferenceMismatchError(ValueError):
    """A record's CHROM is absent/duplicated in the reference or REF disagrees."""


@dataclass(frozen=True)
class VcfHeader:
    """The VCF header.

    ``meta_lines`` holds the ``##`` meta-information lines verbatim,
    without their line terminators and in input order.  ``samples``
    holds the sample names taken from the single ``#CHROM`` header line
    (an empty tuple for sample-less VCF).
    """

    meta_lines: tuple[str, ...] = ()
    samples: tuple[str, ...] = ()

    @property
    def column_names(self) -> tuple[str, ...]:
        """All column names as declared by the ``#CHROM`` line."""
        if self.samples:
            return _FIXED_COLUMNS + ("FORMAT",) + self.samples
        return _FIXED_COLUMNS


@dataclass(frozen=True)
class VcfRecord:
    """One VCF data row.

    The fixed columns are ``chrom``, ``pos`` (1-based), ``id``, ``ref``,
    ``alt`` (a tuple of ALT allele strings), ``qual``, ``filter`` and
    ``info``.  ``format_text`` is ``None`` for sample-less VCF; otherwise
    it holds the FORMAT string and ``samples`` holds one entry per
    sample, each a tuple of colon-separated sub-field strings.
    """

    chrom: str
    pos: int
    id: str
    ref: str
    alt: tuple[str, ...]
    qual: str
    filter: str
    info: str
    format_text: str | None = None
    samples: tuple[tuple[str, ...], ...] = ()

    @property
    def alt_text(self) -> str:
        """The ALT column as it appears on disk."""
        return ",".join(self.alt)


@dataclass(frozen=True)
class VcfFile:
    """A parsed VCF document: a header and its records in input order."""

    header: VcfHeader
    records: tuple[VcfRecord, ...] = ()


def _line_error(source: str, line_number: int, message: str) -> VcfFormatError:
    return VcfFormatError(f"{source}:{line_number}: {message}")


def _is_plain_allele(allele: str) -> bool:
    """Whether *allele* is an ordinary sequence allele of real bases.

    The gVCF spanning value ``*``, missing value ``.``, symbolic alleles
    (``<DEL>``) and break-end alleles (``]chr:123]N``) are not plain.
    """
    if not allele or allele == "*" or allele == ".":
        return False
    if allele[0] == "<" or allele[-1] == ">":
        return False
    if "[" in allele or "]" in allele:
        return False
    return True


def _validate_allele(allele: str) -> str:
    """Upper-case and validate one ordinary sequence allele."""
    upper = allele.upper()
    for index, symbol in enumerate(upper):
        if symbol not in _VALID_BASES:
            raise ValueError(
                f"invalid allele symbol {symbol!r} at offset {index} of {allele!r}"
            )
    return upper


def _parse_record_line(
    line: str, number: int, source: str, samples: Sequence[str]
) -> VcfRecord:
    fields = line.split("\t")
    expected = 8 + (1 if samples else 0) + len(samples)
    if len(fields) < _MIN_COLUMNS:
        raise _line_error(
            source,
            number,
            f"expected at least 8 tab-separated columns, got {len(fields)}",
        )
    if samples:
        if len(fields) != expected:
            raise _line_error(
                source,
                number,
                f"expected {expected} columns to match the #CHROM header, got {len(fields)}",
            )
        format_text = fields[8]
        if not format_text:
            raise _line_error(source, number, "empty FORMAT column")
        sample_fields = tuple(tuple(field.split(":")) for field in fields[9:])
    else:
        if len(fields) != _MIN_COLUMNS:
            raise _line_error(
                source,
                number,
                f"expected 8 columns to match the sample-less #CHROM header, "
                f"got {len(fields)}",
            )
        format_text = None
        sample_fields = ()

    chrom, pos_text, ident, ref_text, alt_text, qual, flt, info = fields[:8]

    if not chrom:
        raise _line_error(source, number, "empty CHROM column")
    try:
        pos = int(pos_text)
    except ValueError:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        ) from None
    if pos <= 0:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )

    if not ref_text:
        raise _line_error(source, number, "empty REF allele")
    try:
        ref = _validate_allele(ref_text)
    except ValueError as exc:
        raise _line_error(source, number, str(exc)) from None

    if not alt_text:
        raise _line_error(source, number, "empty ALT column")
    alts: list[str] = []
    for allele in alt_text.split(","):
        if not _is_plain_allele(allele):
            alts.append(allele)
            continue
        try:
            alts.append(_validate_allele(allele))
        except ValueError as exc:
            raise _line_error(source, number, str(exc)) from None
    alt = tuple(alts)

    return VcfRecord(
        chrom=chrom,
        pos=pos,
        id=ident,
        ref=ref,
        alt=alt,
        qual=qual,
        filter=flt,
        info=info,
        format_text=format_text,
        samples=sample_fields,
    )


def _parse_header_line(
    line: str, number: int, source: str
) -> tuple[str, ...]:
    """Validate the ``#CHROM`` line and return its sample names."""
    columns = line.split("\t")
    if tuple(columns[:8]) != _FIXED_COLUMNS:
        raise _line_error(
            source,
            number,
            "the first eight #CHROM header columns must be exactly "
            "#CHROM\\tPOS\\tID\\tREF\\tALT\\tQUAL\\tFILTER\\tINFO",
        )
    tail = columns[8:]
    if not tail:
        return ()
    if tail[0] != "FORMAT":
        raise _line_error(
            source,
            number,
            "the ninth column, when present, must be FORMAT",
        )
    samples = tuple(tail[1:])
    if not samples:
        raise _line_error(source, number, "FORMAT column requires at least one sample")
    if any(not sample for sample in samples):
        raise _line_error(source, number, "empty sample name in #CHROM header")
    return samples


def read_vcf(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Read and validate a whole VCF document from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  ``##`` meta-information lines are
    kept verbatim and in order; exactly one legal ``#CHROM`` line is
    required and every data row must match its columns.  Records are
    returned in input order.

    Raises :class:`VcfFormatError` for malformed input and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        meta_lines: list[str] = []
        samples: tuple[str, ...] | None = None
        header_number = 0
        records: list[VcfRecord] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if line.startswith("##"):
                if samples is not None:
                    raise _line_error(
                        source_name,
                        number,
                        "meta-information line after the #CHROM header",
                    )
                meta_lines.append(line)
            elif line.startswith("#"):
                if samples is not None:
                    raise _line_error(
                        source_name, number, "duplicate #CHROM column header"
                    )
                header_number = number
                samples = _parse_header_line(line, number, source_name)
            elif line == "":
                # Tolerate blank separators but reject trailing blank
                # lines after records? VCF has no blank-line grammar;
                # ignore blank lines before and between records.
                continue
            else:
                if samples is None:
                    raise _line_error(
                        source_name,
                        number,
                        "data row before the #CHROM column header",
                    )
                records.append(
                    _parse_record_line(line, number, source_name, samples)
                )

        if samples is None:
            raise VcfFormatError(
                f"{source_name}: missing #CHROM column header"
            )
        return VcfFile(VcfHeader(tuple(meta_lines), samples), tuple(records))
    finally:
        if close:
            stream.close()


def _reference_index(
    reference: Iterable[SequenceRecord],
) -> dict[str, str]:
    """Build a CHROM -> sequence map, rejecting duplicate identifiers."""
    sequences: dict[str, str] = {}
    for record in reference:
        if record.identifier in sequences:
            raise ReferenceMismatchError(
                f"duplicate reference record {record.identifier!r}"
            )
        sequences[record.identifier] = record.sequence
    return sequences


def _mismatch(
    record: VcfRecord, expected: str, actual: str, offset: int
) -> ReferenceMismatchError:
    return ReferenceMismatchError(
        f"CHROM {record.chrom} POS {record.pos + offset}: REF does not match "
        f"the reference: expected {expected!r}, found {actual!r}"
    )


def _normalize_alleles(
    pos: int, ref: str, alts: Sequence[str]
) -> tuple[int, str, tuple[str, ...]]:
    """Remove the common suffix and prefix shared by all alleles.

    At least one base is always retained per allele and *pos* (1-based)
    is advanced by the number of stripped leading bases.
    """
    # Common suffix: compare up to the shortest allele minus one base.
    suffix = 0
    limits = [min(len(ref), len(alt)) for alt in alts]
    while all(
        suffix < limit - 1
        and ref[len(ref) - 1 - suffix] == alts[i][len(alts[i]) - 1 - suffix]
        for i, limit in enumerate(limits)
    ):
        suffix += 1
    if suffix:
        ref = ref[: len(ref) - suffix]
        alts = tuple(alt[: len(alt) - suffix] for alt in alts)

    # Common prefix: always keep the first base.
    prefix = 0
    while (
        prefix < min(len(ref), min(len(alt) for alt in alts)) - 1
        and all(allele[prefix] == ref[prefix] for allele in alts)
    ):
        prefix += 1
    if prefix:
        ref = ref[prefix:]
        alts = tuple(allele[prefix:] for allele in alts)
        pos += prefix

    return pos, ref, alts


def normalize_record(
    record: VcfRecord,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfRecord:
    """Normalize one record against *reference*.

    *reference* is either a mapping of CHROM to upper-case reference
    sequence or an iterable of :class:`~genome_variant.sequence_io.SequenceRecord`
    (duplicate identifiers raise :class:`ReferenceMismatchError`).

    The REF fragment at POS is always verified.  Records whose ALT
    contains a symbolic, break-end, spanning (``*``) or missing (``.``)
    allele are returned unchanged apart from REF/ALT case normalization
    performed at parse time.  Otherwise all sequence alleles are trimmed
    of their shared suffix and prefix (one base is always kept) and, when
    allele lengths differ, left-shifted across repeated reference bases
    to the smallest POS representing the same haplotype, re-trimming
    after every shift.  ID, QUAL, FILTER, INFO, FORMAT and sample text,
    as well as ALT order, are preserved.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
    else:
        sequences = _reference_index(reference)

    try:
        chromosome = sequences[record.chrom]
    except KeyError:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom!r} is missing from the reference"
        ) from None

    if record.pos - 1 + len(record.ref) > len(chromosome) or record.pos < 1:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: REF of length "
            f"{len(record.ref)} is out of bounds for a reference of length "
            f"{len(chromosome)}"
        )

    expected = chromosome[record.pos - 1 : record.pos - 1 + len(record.ref)].upper()
    if expected != record.ref:
        raise _mismatch(record, expected, record.ref, 0)

    shiftable = all(_is_plain_allele(allele) for allele in record.alt)
    if not shiftable:
        return record

    pos, ref, alts = _normalize_alleles(record.pos, record.ref, record.alt)

    # Left-align: only alleles of differing lengths can be shifted.
    # Extend one base to the left when every allele shares the first base
    # of the window, then strip the shared suffix; repeat until the window
    # cannot move further left.
    if len({len(ref), *(len(alt) for alt in alts)}) > 1:
        while pos > 1:
            preceding = chromosome[pos - 2].upper()
            window = tuple(preceding + allele for allele in (ref, *alts))
            window_ref, window_alts = window[0], window[1:]
            if not all(allele[0] == window_ref[0] for allele in window_alts):
                break
            pos -= 1
            pos, ref, alts = _normalize_alleles(pos, window_ref, window_alts)
            if len({len(ref), *(len(alt) for alt in alts)}) <= 1:
                break

    return replace(record, pos=pos, ref=ref, alt=alts)


def normalize_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfFile:
    """Normalize every record of *document* against *reference*.

    Record order is preserved; see :func:`normalize_record` for the
    per-record rules.  Every record is validated before the normalized
    document is returned, so a raised error means the caller received no
    partial result.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        records_source: Iterable[SequenceRecord] | None = None
    else:
        records_source = list(reference)
        sequences = _reference_index(records_source)

    normalized = tuple(
        normalize_record(record, sequences) for record in document.records
    )
    return VcfFile(document.header, normalized)


def _record_line(record: VcfRecord) -> str:
    fields = [
        record.chrom,
        str(record.pos),
        record.id,
        record.ref,
        record.alt_text,
        record.qual,
        record.filter,
        record.info,
    ]
    if record.format_text is not None:
        fields.append(record.format_text)
        fields.extend(":".join(sample) for sample in record.samples)
    return "\t".join(fields)


def render_vcf(document: VcfFile) -> str:
    """Serialize *document* to VCF text.

    Output uses tabs and ``"\\n"`` line endings and always ends with
    exactly one trailing newline; a record-less VCF still writes the
    complete header (``##`` lines followed by the ``#CHROM`` line).
    """
    lines = list(document.header.meta_lines)
    lines.append("\t".join(document.header.column_names))
    lines.extend(_record_line(record) for record in document.records)
    return "\n".join(lines) + "\n"


def write_vcf(
    document: VcfFile,
    output: "str | os.PathLike[str] | io.TextIOBase",
) -> None:
    """Write *document* to *output* as VCF text.

    Tabs and ``"\\n"`` are used throughout with exactly one trailing
    newline; an empty-record VCF still writes the complete header.
    """
    text = render_vcf(document)
    if isinstance(output, io.IOBase):
        output.write(text)
    elif isinstance(output, (str, os.PathLike)):
        with open(os.fspath(output), "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
    else:
        raise TypeError("output must be a text path or a text stream")

